{"results": [{"id": "hp_doc_0628a602fb1b673d6aa73b26878aac95f4e50ac7c1701db2c5cd99e0ed2eb9bf", "title": "Elegy (Corigliano)", "text": "Elegy is an orchestral composition by the American composer John Corigliano. It was first performed by the San Francisco Symphony under the direction Verne Sellin at the War Memorial Opera House on June 1, 1966. The piece is dedicated to the composer Samuel Barber.", "score": 35.1882}, {"id": "hp_doc_a77c64feec1ab3c813871c9644bf4100f76acd54d8086cdc2506679bf88bd57b", "title": "War Memorial Opera House", "text": "The War Memorial Opera House in San Francisco, California is located on the western side of Van Ness Avenue across from the rear facade of City Hall. It is part of the San Francisco War Memorial and Performing Arts Center. It has been the home of the San Francisco Opera since opening night in 1932.", "score": 29.9576}, {"id": "hp_doc_0b9dab2b6a6eb5a7e4f71c2fc2654e8085d6ba3fd5a33d9d02f9019c27ce382f", "title": "Van Ness Avenue", "text": "Van Ness Avenue is a north-south thoroughfare in San Francisco, California, running from Market St north to the Bay. Originally named Marlette Street, the street was renamed Van Ness Avenue in honor of the city's seventh mayor, James Van Ness. Van Ness Avenue begins at Market Street near the Civic Center, and extends north to end at Bay Street at Fort Mason. Of the more striking landmarks along the route are the San Francisco City Hall, the War Memorial Opera House, and Louise M. Davies Symphony Hall.", "score": 20.7267}], "remaining_searches": 2}
